head.script:
scwin.unitTest = function() {
    // Init test
    WebSquare.wUnit.start();
    // Step test 0: 0. 속성키인 calendarValueType을 yearMonthDateTimeSec설정, validCheck옵션을 true로 설정한다.
    // Set the attribute key calendarValueType to yearMonthDateTimeSec and set the validCheck option to true.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_1').getAttribute('calendarValueType')", "yearMonthDateTimeSec");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_1').getAttribute('validCheck')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    // Step test 1: 1. inputCalendar_WPF-989_(WSQ-2232).xml 파일을 실행한다.
    // - 1. Run the inputCalendar_WPF-989_ (WSQ-2232) .xml file.
    // Verify 1: 1. inputCalendar_WPF-989_(WSQ-2232).xml 실행된다.
    // - 1. inputCalendar_WPF-989_ (WSQ-2232) .xml is executed.
    // Step test 2: 2. inputCalendar(달력버튼)를 실행하고 캘린더창 우측 하단에 확인 버튼을 클릭한다.
    // - 2. Run inputCalendar (calendar button) and click the OK button at the bottom right of the calendar window.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_img').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_time_confirm')[0].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_img').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // Verify 2: 2. 에러없이 날짜가 입력된다.(이전에는 날짜형식이 잘못되었습니다.라는 alert창이 보임)
    // 2. The date is entered without an error (previously an invalid date format is displayed in the alert window)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_1_input').value != ''", "true");
    // Run test
    WebSquare.wUnit.run();
    // Stop test
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    // Function test
    // Created by Sang.Do
    // Created date 17-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
